mapper.insert:
INSERT INTO mail_receiver (
    mail_id, receiver_id, receiver_type, is_read, is_deleted, receive_time, mail_send_time
)
SELECT mail_id, #{receiverId}, #{receiverType}, #{read}, #{deleted}, NOW(), send_time
FROM mail WHERE mail_id = #{mailId}

mapper.select:
SELECT COUNT(1) > 0
FROM mail m
WHERE m.mail_id = #{mailId}
  AND m.mail_status = 1
  AND (
      m.sender_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM mail_receiver mr
          WHERE mr.mail_id = m.mail_id
            AND mr.receiver_id = #{userId}
      )
  )

SELECT COUNT(1) > 0
FROM mail
WHERE mail_id = #{mailId}
  AND sender_id = #{userId}
  AND sender_deleted = FALSE
  AND mail_status = 1

SELECT COUNT(1) > 0
FROM mail
WHERE mail_id = #{mailId}
  AND sender_id = #{userId}
  AND sender_deleted = TRUE
  AND mail_status = 1

mapper.update:
UPDATE mail_receiver
SET is_read = #{isRead}
WHERE mail_id = #{mailId}
  AND receiver_id = #{userId}
  AND is_deleted = FALSE

UPDATE mail_receiver
SET is_deleted = TRUE
WHERE mail_id = #{mailId}
  AND receiver_id = #{userId}

UPDATE mail
SET sender_deleted = TRUE
WHERE mail_id = #{mailId}
  AND sender_id = #{senderId}

UPDATE mail_receiver
SET is_deleted = FALSE
WHERE mail_id = #{mailId}
  AND receiver_id = #{userId}
  AND is_deleted = TRUE

UPDATE mail
SET sender_deleted = FALSE
WHERE mail_id = #{mailId}
  AND sender_id = #{senderId}
  AND sender_deleted = TRUE
  AND mail_status = 1

mapper.delete:
DELETE FROM mail_receiver
WHERE mail_id = #{mailId}
  AND receiver_id = #{userId}
  AND is_deleted = TRUE

mapper.update:
UPDATE mail
SET mail_status = #{mailStatus}
WHERE mail_id = #{mailId}

UPDATE mail
SET is_spam = #{isSpam}
WHERE mail_id = #{mailId}
